WITH kept_keys AS (SELECT manager_id, dept_id FROM employees EXCEPT ALL SELECT manager_id, dept_id FROM employees WHERE job_title <> 'Director'), reconciled AS (SELECT s.* FROM employees s INNER JOIN kept_keys k ON s.manager_id = k.manager_id AND s.dept_id = k.dept_id) SELECT id, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, CASE WHEN job_title RLIKE '^(Intern|Engineer)$' THEN 'EXTENDED' WHEN job_title RLIKE '^(Analyst|Manager)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS job_title_zone FROM reconciled ORDER BY id, job_title_zone
